'use strict';

// Tasa de gestion por pedido: un centavo base mas un centavo por unidad.
function cost(units) {
  if (!Number.isInteger(units) || units < 0) throw new TypeError(`unidades no validas: ${units}`);
  return units + 1;
}

module.exports = { cost };

